import { showGlobalProgressModal } from "../../ui_utilities"

export const internetArchiveUrlProtocol = "a2ia://"

export const generateUrlFromInternetArchiveId = (identifier: string): URL => {
  return new URL(internetArchiveUrlProtocol + identifier)
}

export const getDiskImageUrlFromIdentifier = async (identifier: string) => {
  let newDiskImageUrl: URL | undefined
  const detailsUrl = `https://archive.org/details/${identifier}?output=json`

  // Parse the metadata JSON and find the disk image file URL.
  // Prefer direct ia*.archive.org URL (has CORS headers) over archive.org/download/ redirect.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const extractDiskUrl = (json: any) => {
    const metadata = json?.metadata
    const files = json?.files

    if (metadata && metadata.emulator_ext && files) {
      const emulatorExt = metadata.emulator_ext.toString().toLowerCase()
      console.log(`🗂️ IA metadata: emulator_ext=${emulatorExt}`)

      Object.keys(files).forEach((file) => {
        if (file.toLowerCase().endsWith(emulatorExt)) {
          // Use archive.org/download/ URL — allorigins /raw can follow the redirect correctly
          newDiskImageUrl = new URL(`https://archive.org/download/${identifier}${file}`)
          console.log(`✅ Found disk image: ${newDiskImageUrl.toString()}`)
        }
      })
      if (!newDiskImageUrl) {
        console.warn(`❌ No file matching extension "${emulatorExt}" in IA item`)
      }
    } else {
      console.warn(`❌ IA metadata missing emulator_ext or files`, metadata)
    }
  }

  showGlobalProgressModal(true)
  try {
    const fetchMethods = [
      // 1. Direct fetch (works in Electron, no CORS restriction)
      async () => {
        const r = await fetch(detailsUrl)
        if (!r.ok) throw new Error(`HTTP ${r.status}`)
        return r.json()
      },
      // 2. corsfix
      async () => {
        console.log("Direct fetch failed, trying proxy.corsfix.com...")
        const r = await fetch("https://proxy.corsfix.com/?" + detailsUrl)
        if (!r.ok) throw new Error(`HTTP ${r.status}`)
        return r.json()
      },
    ]

    for (const fetchFn of fetchMethods) {
      try {
        const json = await fetchFn()
        extractDiskUrl(json)
        if (newDiskImageUrl) break
      } catch (e) {
        console.log(`IA metadata fetch method failed: ${e}`)
      }
    }
  } finally {
    showGlobalProgressModal(false)
  }

  if (!newDiskImageUrl) {
    console.error(`❌ All fetch methods failed for IA identifier: ${identifier}`)
  }

  return newDiskImageUrl
}
